def resolve(cwd, repo_root):
    rules = {}
    for directory in ancestors(cwd, up_to=repo_root):   # root → cwd
        path = directory / "AGENTS.md"
        if path.exists():
            rules.update(parse(path))      # nearer file wins on conflict
    return rules

# TOOL — an action, with consequences
@tool("create_payment_link",
      description="Create a Stripe payment link. Use when asked to bill.")
def create_payment_link(amount_cents: int, currency: str, *, caller) -> str:
    if not caller.has_scope("payments:write"):
        return "REFUSED: this connection is read-only"
    return stripe.PaymentLink.create(amount=amount_cents, currency=currency).url

