while True:
    state = a2a.poll(task.id)
    if state.status == "completed":
        return state.result
    if state.status == "rejected":
        return escalate_to_human(state.reason)
    if state.status == "input-required":
        a2a.reply(task.id, answer_for(state.question))
    sleep(state.retry_after)

def review(functions, parent_ctx):
    reports = run_parallel([
        spawn_subagent(
            task=f"Review {fn.path}:{fn.name} for error handling only. "
                 f"Reply with at most 5 lines: findings or 'none'.",
            context="fresh",
        )
        for fn in functions
    ], on_error=lambda fn, e: f"{fn.name}: FAILED ({e})")

    return summarise(reports)      # parent sees ~20 short reports,
                                   # never the 20 files
